{
  "application": "report-generation",
  "case_id": "case-education-cs-past-papers-biek-en",
  "language": "en",
  "report": {
    "type": "trend-analysis",
    "audience": "educators and curriculum planners",
    "tone": "analytical, detailed, educational"
  },
  "brief": {
    "title": "BIEK Computer Science 12th Class Past Paper Analysis (2015–2025)",
    "one_liner": "A comprehensive trend analysis of question types, frequency patterns, and topic distribution across 11 years of BIEK Computer Science HSC Part-2 examination papers.",
    "goal": "Enable educators, curriculum planners, and students to understand how the BIEK Computer Science exam has evolved over time — identifying shifts in question type distribution, high-frequency years, and patterns that can inform exam preparation strategies and curriculum alignment."
  },
  "required_sections": [
    {
      "section_id": "overview",
      "title": "Dataset & Examination Overview",
      "objective": "Summarize the scope of the dataset including total questions, year range, and question type breakdown."
    },
    {
      "section_id": "yearly-distribution",
      "title": "Year-by-Year Question Volume Analysis",
      "objective": "Analyze how the total number of questions and the mix of question types have changed from 2015 to 2025, identifying any notable increases, decreases, or anomalies."
    },
    {
      "section_id": "question-type-analysis",
      "title": "Question Type Composition & Trends",
      "objective": "Break down the proportion of MCQs, Short Questions, and Long Questions across years and assess whether the exam structure has remained stable or shifted over time."
    },
    {
      "section_id": "topic-patterns",
      "title": "Recurring Topics & Question Content Patterns",
      "objective": "Perform a text-level analysis of the question column to identify frequently recurring keywords, topics, or concepts across years and question types."
    },
    {
      "section_id": "exam-prep-insights",
      "title": "Strategic Insights for Exam Preparation",
      "objective": "Synthesize findings into actionable recommendations for students and teachers regarding which question types and topics to prioritize based on historical patterns."
    },
    {
      "section_id": "conclusions",
      "title": "Conclusions & Limitations",
      "objective": "Summarize key findings and note any data limitations such as missing years, supplementary vs. annual paper distinctions, or encoding considerations."
    }
  ],
  "kpis": [
    {
      "name": "Total Questions per Year",
      "description": "The count of all questions (MCQs, Short, Long) appearing in each examination year."
    },
    {
      "name": "Question Type Ratio",
      "description": "The percentage share of MCQs, Short Questions, and Long Questions relative to the total for each year and overall."
    },
    {
      "name": "Year-over-Year Change",
      "description": "The absolute and percentage change in total question count from one year to the next."
    },
    {
      "name": "Average Questions per Type",
      "description": "The mean number of questions per type across all years, serving as a baseline for identifying outlier years."
    }
  ],
  "analysis_dimensions": [
    "year",
    "type",
    "question"
  ]
}

